const SUPPORTED_LANGS = ['en', 'sk', 'cs', 'de', 'pl'];
const STATIC_PAGES = { '': 'index', 'about': 'about', 'skills': 'skills', 'drones': 'drones', 'expertise': 'expertise', 'contact': 'contact', 'services': 'services', 'blog/': 'blog' };
// services only exists in EN and SK; other languages fall back (cs -> sk, de/pl -> en)
const PAGE_LANGS = { services: ['en', 'sk'] };
const LANG_FALLBACK = { cs: 'sk', de: 'en', pl: 'en', sk: 'en', en: 'en' };

let currentLang = 'en';
try {
  const path = window.location.pathname;
  const m = path.match(/^\/(en|sk|cs|de|pl)(\/|$)/);
  const staticLang = document.documentElement.getAttribute('data-i18n-static');
  if (staticLang && translations[staticLang]) {
    currentLang = staticLang;
    try { localStorage.setItem('ms_lang', staticLang); } catch (e) {}
  } else if (m) {
    currentLang = m[1];
  } else if (path.endsWith('-sk') || path.endsWith('-sk.html') || path.includes('/sk/')) {
    currentLang = 'sk';
  } else if (path.includes('/cs/')) {
    currentLang = 'cs';
  } else if (path.includes('/de/')) {
    currentLang = 'de';
  } else if (path.includes('/pl/')) {
    currentLang = 'pl';
  } else {
    currentLang = localStorage.getItem('ms_lang') || document.documentElement.lang || 'en';
  }
  if (!translations[currentLang]) currentLang = 'en';
} catch (e) {
  currentLang = 'en';
}

// URL of the current static page in another language (null when not on a /{lang}/ page)
function staticUrlFor(lang) {
  const m = window.location.pathname.match(/^\/(en|sk|cs|de|pl)\/(.*)$/);
  if (!m) return null;
  let rest = m[2].replace(/index\.html$/, '').replace(/\.html$/, '');
  if (rest === 'blog') rest = 'blog/';
  const pageId = STATIC_PAGES[rest];
  if (!pageId) return null;
  let target = lang;
  const avail = PAGE_LANGS[pageId];
  if (avail && !avail.includes(target)) {
    target = avail.includes(LANG_FALLBACK[lang]) ? LANG_FALLBACK[lang] : 'en';
  }
  return `/${target}/${rest}` + window.location.hash;
}

function switchLanguage(lang) {
  if (!translations[lang]) lang = 'en';
  currentLang = lang;
  try {
    localStorage.setItem('ms_lang', lang);
  } catch(e) {}

  // Intelligent URL routing for language-specific static subpages
  if (typeof window !== 'undefined' && window.location) {
    const path = window.location.pathname;
    const staticTarget = staticUrlFor(lang);
    if (staticTarget) {
      window.location.href = staticTarget;
      return;
    }
    const pairedPages = ['services', 'privacy', 'terms', 'disclaimer'];
    for (const page of pairedPages) {
      if (path === `/${page}` || path === `/${page}.html`) {
        if (lang === 'sk') {
          window.location.href = `/${page}-sk`;
          return;
        }
      } else if (path === `/${page}-sk` || path === `/${page}-sk.html`) {
        if (lang !== 'sk') {
          window.location.href = `/${page}`;
          return;
        }
      }
    }

    // Blog article localized routing
    if (path.includes('/blog/posts/')) {
      const cleanSlug = path.replace(/^\/blog\/posts\//, '').replace(/^(sk|cs|de|pl)\//, '').replace(/\.html$/, '');
      if (cleanSlug) {
        if (lang === 'en') {
          window.location.href = `/blog/posts/${cleanSlug}`;
          return;
        } else {
          window.location.href = `/blog/posts/${lang}/${cleanSlug}`;
          return;
        }
      }
    }
  }

  applyTranslations();
  if (typeof loadDynamicPostsHome === 'function') loadDynamicPostsHome();
  if (typeof renderBlogIndexPosts === 'function') renderBlogIndexPosts();
  window.dispatchEvent(new CustomEvent('languageChanged', { detail: { lang } }));
}

// Expose globally
window.switchLanguage = switchLanguage;
window.applyTranslations = applyTranslations;
window.currentLang = currentLang;

function applyTranslations() {
  const d = translations[currentLang] || translations.en;
  
  // 1. Update button active classes across any lang switcher
  const langButtons = {
    'en': document.querySelectorAll('#btnEn, .btn-lang-en, [data-lang-btn="en"]'),
    'sk': document.querySelectorAll('#btnSk, .btn-lang-sk, [data-lang-btn="sk"]'),
    'cs': document.querySelectorAll('#btnCs, .btn-lang-cs, [data-lang-btn="cs"]'),
    'de': document.querySelectorAll('#btnDe, .btn-lang-de, [data-lang-btn="de"]'),
    'pl': document.querySelectorAll('#btnPl, .btn-lang-pl, [data-lang-btn="pl"]')
  };
  
  Object.keys(langButtons).forEach(k => {
    langButtons[k].forEach(b => {
      if (k === currentLang) b.classList.add('active');
      else b.classList.remove('active');
    });
  });

  // Pre-rendered /{lang}/ pages already contain the right texts, titles and links.
  if (document.documentElement.getAttribute('data-i18n-static') === currentLang) {
    document.documentElement.lang = currentLang;
    return;
  }

  // 2. Instant blog index pre-rendered post group switcher
  const enGroup = document.getElementById('postsEn');
  const skGroup = document.getElementById('postsSk');
  const deGroup = document.getElementById('postsDe');
  const plGroup = document.getElementById('postsPl');
  if (enGroup && skGroup && deGroup && plGroup) {
    enGroup.style.display = currentLang === 'en' ? 'block' : 'none';
    skGroup.style.display = currentLang === 'sk' ? 'block' : 'none';
    deGroup.style.display = currentLang === 'de' ? 'block' : 'none';
    plGroup.style.display = currentLang === 'pl' ? 'block' : 'none';
  }

  document.documentElement.lang = currentLang;
  if (d.docTitle) document.title = d.docTitle;
  
  const descEl = document.querySelector('meta[name="description"]');
  if (descEl && d.docDesc) descEl.setAttribute('content', d.docDesc);
  
  const ogTitleEl = document.querySelector('meta[property="og:title"]');
  if (ogTitleEl && d.ogTitle) ogTitleEl.setAttribute('content', d.ogTitle);
  
  const ogDescEl = document.querySelector('meta[property="og:description"]');
  if (ogDescEl && d.ogDesc) ogDescEl.setAttribute('content', d.ogDesc);

  // 3. Generic Update: any element with data-i18n matching key
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (d[key] !== undefined) {
      const val = d[key];
      if (typeof val === 'string' && val.includes('<') && val.includes('>')) {
        el.innerHTML = val;
      } else {
        el.textContent = val;
      }
    }
  });

  // 4. Protected Layout Containers List
  const PROTECTED_TAGS = ['SECTION', 'MAIN', 'NAV', 'HEADER', 'FOOTER', 'BODY', 'HTML', 'DIV', 'ARTICLE', 'ASIDE'];

  // Generic Update: any element with ID matching key in dictionary (skipping structural containers)
  Object.keys(d).forEach(key => {
    const val = d[key];
    const el = document.getElementById(key);
    if (el) {
      if (PROTECTED_TAGS.includes(el.tagName) && !el.hasAttribute('data-i18n')) {
        return;
      }
      if (typeof val === 'string' && val.includes('<') && val.includes('>')) {
        el.innerHTML = val;
      } else {
        el.textContent = val;
      }
    }
  });

  // 5. Dynamic link routing according to active language
  const targetServicesHref = (currentLang === 'sk' || currentLang === 'cs') ? '/services-sk' : '/services';
  document.querySelectorAll('a[href="/services"], a[href="/services-sk"], #navProducts, #navServices, .home-prod-card').forEach(el => {
    if (el.tagName === 'A') {
      const h = el.getAttribute('href');
      if (h === '/services' || h === '/services-sk') {
        el.setAttribute('href', targetServicesHref);
      }
    }
  });

  const legalPages = ['privacy', 'terms', 'disclaimer'];
  legalPages.forEach(p => {
    const targetHref = (currentLang === 'sk' || currentLang === 'cs') ? `/${p}-sk` : `/${p}`;
    document.querySelectorAll(`a[href="/${p}"], a[href="/${p}-sk"]`).forEach(el => {
      el.setAttribute('href', targetHref);
    });
  });
}

async function loadDynamicPostsHome() {
  try {
    const res = await fetch('/blog/posts.json');
    if (!res.ok) return;
    const posts = await res.json();
    if (!Array.isArray(posts) || posts.length === 0) return;
    const container = document.getElementById('homeBlogGrid');
    if (!container) return;
    const d = translations[currentLang] || translations.en;

    container.innerHTML = posts.slice(0, 3).map(p => {
      let title = p.title;
      let excerpt = p.excerpt;
      let date = p.displayDate;
      let targetUrl = p.url;

      if (currentLang === 'sk' || (currentLang === 'cs' && !p.urlCs)) {
        title = p.titleSk || p.title;
        excerpt = p.excerptSk || p.excerpt;
        date = p.displayDateSk || p.displayDate;
        targetUrl = p.urlSk || p.url;
      } else if (currentLang === 'cs') {
        title = p.titleCs || p.titleSk || p.title;
        excerpt = p.excerptCs || p.excerptSk || p.excerpt;
        date = p.displayDateCs || p.displayDateSk || p.displayDate;
        targetUrl = p.urlCs || p.urlSk || p.url;
      } else if (currentLang === 'de') {
        title = p.titleDe || p.title;
        excerpt = p.excerptDe || p.excerpt;
        date = p.displayDateDe || p.displayDate;
        targetUrl = p.urlDe || p.url;
      } else if (currentLang === 'pl') {
        title = p.titlePl || p.title;
        excerpt = p.excerptPl || p.excerpt;
        date = p.displayDatePl || p.displayDate;
        targetUrl = p.urlPl || p.url;
      }

      return `
<a href="/${targetUrl}" class="blog-card fade-in visible">
  <div class="blog-card-date">${date}</div>
  <h3>${title}</h3>
  <p>${excerpt}</p>
  <div class="blog-card-arrow">${d.blogReadPost || 'Read post'} <span>→</span></div>
</a>`;
    }).join('');
  } catch(e){}
}

async function renderBlogIndexPosts() {
  const enGroup = document.getElementById('postsEn');
  const skGroup = document.getElementById('postsSk');
  const deGroup = document.getElementById('postsDe');
  const plGroup = document.getElementById('postsPl');
  if (enGroup && skGroup && deGroup && plGroup) {
    enGroup.style.display = currentLang === 'en' ? 'block' : 'none';
    skGroup.style.display = currentLang === 'sk' ? 'block' : 'none';
    deGroup.style.display = currentLang === 'de' ? 'block' : 'none';
    plGroup.style.display = currentLang === 'pl' ? 'block' : 'none';
    return;
  }
  const container = document.getElementById('postContainer');
  if (!container) return;
  try {
    const res = await fetch('/blog/posts.json');
    if (!res.ok) return;
    const posts = await res.json();
    if (!Array.isArray(posts) || posts.length === 0) return;
    const d = translations[currentLang] || translations.en;

    container.innerHTML = posts.map(p => {
      let title = p.title;
      let excerpt = p.excerpt;
      let date = p.displayDate;
      let readTime = p.readTime || '5 min read';
      let targetUrl = p.url;

      if (currentLang === 'sk' || (currentLang === 'cs' && !p.urlCs)) {
        title = p.titleSk || p.title;
        excerpt = p.excerptSk || p.excerpt;
        date = p.displayDateSk || p.displayDate;
        readTime = p.readTimeSk || p.readTime;
        targetUrl = p.urlSk || p.url;
      } else if (currentLang === 'cs') {
        title = p.titleCs || p.title;
        excerpt = p.excerptCs || p.excerpt;
        date = p.displayDateCs || p.displayDate;
        readTime = p.readTimeCs || p.readTime;
        targetUrl = p.urlCs || p.url;
      } else if (currentLang === 'de') {
        title = p.titleDe || p.title;
        excerpt = p.excerptDe || p.excerpt;
        date = p.displayDateDe || p.displayDate;
        readTime = p.readTimeDe || p.readTime;
        targetUrl = p.urlDe || p.url;
      } else if (currentLang === 'pl') {
        title = p.titlePl || p.title;
        excerpt = p.excerptPl || p.excerpt;
        date = p.displayDatePl || p.displayDate;
        readTime = p.readTimePl || p.readTime;
        targetUrl = p.urlPl || p.url;
      }

      const tagsHtml = (p.tags || []).map(t => `<span>${t}</span>`).join('');

      return `
<a href="/${targetUrl}" class="post-item fade-in visible" lang="${currentLang}">
  <div class="post-top">
    <span class="post-date">${date}</span>
    <span class="post-read">${readTime}</span>
  </div>
  <h2>${title}</h2>
  <p>${excerpt}</p>
  <div class="post-tags">${tagsHtml}</div>
</a>`;
    }).join('');
  } catch(e){}
}

// Scroll / Fade-in Initialization
function initScrollObserver() {
  document.querySelectorAll('.fade-in').forEach(el => el.classList.add('visible'));
}

// Initialize
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    initScrollObserver();
    applyTranslations();
    if ('requestIdleCallback' in window) {
      requestIdleCallback(loadDynamicPostsHome);
      requestIdleCallback(renderBlogIndexPosts);
    } else {
      setTimeout(loadDynamicPostsHome, 50);
      setTimeout(renderBlogIndexPosts, 50);
    }
  });
} else {
  initScrollObserver();
  applyTranslations();
  if ('requestIdleCallback' in window) {
    requestIdleCallback(loadDynamicPostsHome);
    requestIdleCallback(renderBlogIndexPosts);
  } else {
    setTimeout(loadDynamicPostsHome, 50);
    setTimeout(renderBlogIndexPosts, 50);
  }
}

// Mobile nav toggle
document.querySelector('.mobile-toggle')?.addEventListener('click', function() {
  const nav = document.querySelector('.nav-links');
  const isOpen = nav?.classList.toggle('open');
  this.setAttribute('aria-expanded', isOpen);
});

document.addEventListener('click', function(e) {
  const nav = document.querySelector('.nav-links');
  const toggle = document.querySelector('.mobile-toggle');
  if (nav && nav.classList.contains('open') && !nav.contains(e.target) && !toggle?.contains(e.target)) {
    nav.classList.remove('open');
    toggle?.setAttribute('aria-expanded', 'false');
  }
});

// Lead form
document.getElementById('leadForm')?.addEventListener('submit', async function(e) {
  e.preventDefault();
  const btn = document.getElementById('subscribeBtn');
  const status = document.getElementById('leadStatus');
  const email = document.getElementById('leadEmail')?.value.trim();
  if (!email) return;
  btn.disabled = true;
  btn.textContent = '...';
  status.textContent = '';
  status.className = 'lead-status';
  try {
    const res = await fetch('/api/subscribe', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, source: 'marianstancik.dev' })
    });
    const data = await res.json();
    if (res.ok && data.status === 'ok') {
      status.textContent = currentLang === 'sk' ? '✅ Prihlásené! Skontrolujte si schránku.' : (currentLang === 'de' ? '✅ Abonniert! Prüfen Sie Ihr Postfach.' : (currentLang === 'pl' ? '✅ Zapisano! Sprawdź skrzynkę.' : '✅ Subscribed! Check your inbox.'));
      status.className = 'lead-status lead-success';
      document.getElementById('leadEmail').value = '';
    } else {
      status.textContent = '❌ ' + (data.error || 'Error. Try again.');
      status.className = 'lead-status lead-error';
    }
  } catch (err) {
    status.textContent = '❌ Network error.';
    status.className = 'lead-status lead-error';
  }
  btn.disabled = false;
  btn.textContent = translations[currentLang]?.subscribeBtn || 'Subscribe';
});

// Contact form
document.getElementById('contactForm')?.addEventListener('submit', async function(e) {
  e.preventDefault();
  const btn = document.getElementById('contactSubmitBtn');
  const status = document.getElementById('contactStatus');
  const name = document.getElementById('contactName')?.value.trim();
  const email = document.getElementById('contactEmail')?.value.trim();
  const message = document.getElementById('contactMessage')?.value.trim();
  const hp = document.getElementById('contactHp')?.value;
  
  if (hp) return; // Silent honeypot drop
  if (!email || !message) return;
  
  btn.disabled = true;
  btn.textContent = '...';
  status.textContent = '';
  status.className = 'lead-status';
  
  try {
    const res = await fetch('/api/subscribe', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name,
        email,
        message,
        source: 'contact_form'
      })
    });
    const data = await res.json();
    if (res.ok && data.status === 'ok') {
      status.textContent = currentLang === 'sk' ? '✅ Správa úspešne odoslaná! Ozvem sa do 24 hodín.' :
        (currentLang === 'de' ? '✅ Nachricht erfolgreich gesendet! Antwort innerhalb von 24h.' :
        (currentLang === 'pl' ? '✅ Wiadomość wysłana! Odpowiem w ciągu 24h.' :
        '✅ Message sent successfully! Fast reply within 24h.'));
      status.className = 'lead-status lead-success';
      document.getElementById('contactForm').reset();
    } else {
      status.textContent = '❌ ' + (data.error || 'Error sending message. Please try again.');
      status.className = 'lead-status lead-error';
    }
  } catch (err) {
    status.textContent = '❌ Network error. Write directly to marianstancik@agentmail.to';
    status.className = 'lead-status lead-error';
  }
  btn.disabled = false;
  btn.textContent = translations[currentLang]?.contactSubmitBtn || 'Send Message →';
});

